// รับ array ราคาจาก admin.html
const body = $input.first().json.body || $input.first().json;
const prices = body.prices || [];

if (prices.length === 0) {
  return [{ json: { sql: 'SELECT 1;', count: 0 } }];
}

// สร้าง VALUES string สำหรับ UPSERT
const esc = (s) => String(s || '').replace(/'/g, "''");

const values = prices.map(p => {
  const mc = esc(p.model_code);
  const vc = esc(p.variant_code || '');
  const pr = parseInt(p.price) || 0;
  const ft = esc(p.file_type || 'small');
  return `('${mc}','${vc}',${pr},'${ft}',NOW())`;
}).join(',');

const sql = `INSERT INTO price_list (model_code, variant_code, price, file_type, updated_at)
VALUES ${values}
ON CONFLICT (model_code, variant_code)
DO UPDATE SET
  price = EXCLUDED.price,
  file_type = EXCLUDED.file_type,
  updated_at = NOW();`;

return [{ json: { sql, count: prices.length } }];
